from pathlib import Path
import json,re
from openpyxl import Workbook
from openpyxl.styles import Font,PatternFill,Alignment
from openpyxl.utils import get_column_letter
from openpyxl.cell import WriteOnlyCell

P=Path(__file__).parent
d=json.loads((P/'dist/data.json').read_text());reg=json.loads((P/'dist/registry.json').read_text());pub=json.loads((P/'dist/public-energy.json').read_text())
w=Workbook(write_only=True)
def sheet(name,headers,rows,widths=None):
 s=w.create_sheet(name);s.freeze_panes='C2';s.sheet_view.showGridLines=False
 for i,h in enumerate(headers,1):s.column_dimensions[get_column_letter(i)].width=(widths or {}).get(i,26 if len(h)<20 else 42)
 cells=[]
 for h in headers:
  c=WriteOnlyCell(s,h);c.font=Font(name='Calibri',bold=True,color='FFFFFF',size=11);c.fill=PatternFill('solid',fgColor='193D2E');c.alignment=Alignment(wrap_text=True,vertical='center');cells.append(c)
 s.append(cells);s.row_dimensions[1].height=42
 n=1
 for row in rows:
  cells=[]
  for v in row:
   c=WriteOnlyCell(s,v)
   if isinstance(v,str):c.data_type='s'
   c.font=Font(name='Calibri',size=11,color='203B30');c.alignment=Alignment(vertical='top',wrap_text=len(row)<30)
   if n%2==0:c.fill=PatternFill('solid',fgColor='F0F3EB')
   cells.append(c)
  s.append(cells);n+=1
 s.auto_filter.ref=f'A1:{get_column_letter(len(headers))}{n}'
 return n-1

notes=[['Назначение','Самостоятельный поиск предприятий и организаций Молдовы с преимущественно дневными закупками электроэнергии от 30 000 MDL/месяц.'],['Дата исследования','17.10.2026'],['Карточки',str(len(d['companies']))+'; добавлено 38 к исходным 80. Список включает группы и бренды, не является счётчиком уникальных юрлиц.'],['Графики','6 опубликованных графиков фабрики/производственной вакансии; 10 общих дневных графиков. Ни один не является почасовым измерением нагрузки.'],['Дневные часы','Не задана пользователем тарифная зона. При наличии интервальных данных отдельно сравнивать 08:00–18:00 и солнечные часы, Europe/Chisinau. Доля свыше половины — буквальное преобладание; не присвоена без измерений.'],['Денежный критерий','≥30 000 MDL в месяц; без верхнего ограничения. Согласовать НДС и перечень объектов. Годовой оборот, мощность кВт и расход кВт·ч не равны счёту.'],['Подтверждение порога','В карточках нет проверенных фактических счетов ≥30 000 MDL/месяц. Это кандидаты на квалификацию.'],['ASP',reg['note']],['ASP дата','12.10.2026; '+str(reg['count'])+' уникальных IDNO. Не полный реестр всех юридических лиц; отбор по производственным кодам.'],['CNED',pub['note']],['CNED период','Январь–апрель 2026, выгрузка 17.06.2026. '+str(len(pub['rows']))+' строк; 428 со средним ≥10 000 кВт·ч. Это не 428 уникальных организаций.'],['Тариф','Расчётный расход MDL = кВт·ч × сопоставимая конечная цена. Цена не подставлена: тариф, напряжение, договор, НДС и даты неизвестны.'],['Ночной фон','Холод, общежития, охрана, насосы, серверы и освещение могут работать вне часов персонала. У муниципалитетов возможны счета уличного освещения.'],['Солнечная генерация','Оценивать покупаемую энергию из сети после собственного производства, а не только общую нагрузку фабрики.'],['Банковские платежи','Частные банковские операции не являются открытым реестром. Публичные счета, документы закупок и отчётность допустимы; договор не равен произведённой оплате. Сумма платежа не определяет дневную долю.'],['Банковская тайна, источник','https://www.bnm.md/files/LAB.pdf — ст.96–97.'],['Дедупликация','ASP: уникальность по IDNO. Карточки: общие бренды объединены там, где связь явно указана. CNED: исходные строки не суммировались, одинаковые названия помечены.'],['Источники','Первоисточник сообщает факт; аналитическая гипотеза отдельно. Контакты не проверялись звонком; сообщений не отправляли.'],['Качество','14 новых карточек — первичное выявление через UPM без отдельной проверки сайта компании; прочие новые карточки содержат просмотренный сайт производителя или вакансию работодателя.'],['Сайт','https://energy-md-atlas.moldset.chatgpt.site']]
